# FILE: Chart.yaml
apiVersion: v2
name: multi-container-app
description: A Helm chart for deploying a multi-container Pod with Fluent Bit sidecar
type: application
version: 0.1.0
appVersion: "1.0.0"
---
# FILE: values.yaml
# Default values for multi-container-app
# This is a YAML-formatted file.
# Declare variables to be passed into your templates.

replicaCount: 1

image:
  repository: nginx
  tag: latest
  pullPolicy: IfNotPresent

fluentbit:
  image:
    repository: fluent/fluent-bit
    tag: latest
    pullPolicy: IfNotPresent
  config:
    # Fluent Bit configuration for log shipping
    input: |
      [INPUT]
        Name tail
        Path /var/log/app/*.log
        Tag app.*
        Refresh_Interval 5
    output: |
      [OUTPUT]
        Name stdout
        Match *

service:
  type: ClusterIP
  port: 80

resources:
  main:
    limits:
      cpu: 500m
      memory: 512Mi
    requests:
      cpu: 250m
      memory: 256Mi
  fluentbit:
    limits:
      cpu: 200m
      memory: 256Mi
    requests:
      cpu: 100m
      memory: 128Mi

nodeSelector: {}

tolerations: []

affinity: {}
---
# FILE: templates/_helpers.tpl
{{- define "multi-container-app.name" -}}
{{- default .Chart.Name .Values.nameOverride | trunc 63 | trimSuffix "-" }}
{{- end }}

{{- define "multi-container-app.fullname" -}}
{{- if .Values.fullnameOverride }}
{{- .Values.fullnameOverride | trunc 63 | trimSuffix "-" }}
{{- else }}
{{- $name := default .Chart.Name .Values.nameOverride }}
{{- if contains $name .Release.Name }}
{{- .Release.Name | trunc 63 | trimSuffix "-" }}
{{- else }}
{{- printf "%s-%s" .Release.Name $name | trunc 63 | trimSuffix "-" }}
{{- end }}
{{- end }}
{{- end }}

{{- define "multi-container-app.chart" -}}
{{- printf "%s-%s" .Chart.Name .Chart.Version | replace "+" "_" | trunc 63 | trimSuffix "-" }}
{{- end }}

{{- define "multi-container-app.labels" -}}
helm.sh/chart: {{ include "multi-container-app.chart" . }}
{{ include "multi-container-app.selectorLabels" . }}
{{- if .Chart.AppVersion }}
app.kubernetes.io/version: {{ .Chart.AppVersion | quote }}
{{- end }}
app.kubernetes.io/managed-by: {{ .Release.Service }}
{{- end }}

{{- define "multi-container-app.selectorLabels" -}}
app.kubernetes.io/name: {{ include "multi-container-app.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
{{- end }}
---
# FILE: templates/deployment.yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "multi-container-app.fullname" . }}
  labels:
    {{- include "multi-container-app.labels" . | nindent 4 }}
spec:
  replicas: {{ .Values.replicaCount }}
  selector:
    matchLabels:
      {{- include "multi-container-app.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      labels:
        {{- include "multi-container-app.selectorLabels" . | nindent 8 }}
    spec:
      containers:
        - name: {{ .Chart.Name }}
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          ports:
            - name: http
              containerPort: 80
              protocol: TCP
          resources:
            {{- toYaml .Values.resources.main | nindent 12 }}
          volumeMounts:
            - name: log-volume
              mountPath: /var/log/app
        - name: fluentbit
          image: "{{ .Values.fluentbit.image.repository }}:{{ .Values.fluentbit.image.tag }}"
          imagePullPolicy: {{ .Values.fluentbit.image.pullPolicy }}
          resources:
            {{- toYaml .Values.resources.fluentbit | nindent 12 }}
          volumeMounts:
            - name: log-volume
              mountPath: /var/log/app
              readOnly: true
            - name: fluentbit-config
              mountPath: /fluent-bit/etc/fluent-bit.conf
              subPath: fluent-bit.conf
      volumes:
        - name: log-volume
          emptyDir: {}
        - name: fluentbit-config
          configMap:
            name: {{ include "multi-container-app.fullname" . }}-fluentbit-config
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
---
# FILE: templates/service.yaml
apiVersion: v1
kind: Service
metadata:
  name: {{ include "multi-container-app.fullname" . }}
  labels:
    {{- include "multi-container-app.labels" . | nindent 4 }}
spec:
  type: {{ .Values.service.type }}
  ports:
    - port: {{ .Values.service.port }}
      targetPort: http
      protocol: TCP
      name: http
  selector:
    {{- include "multi-container-app.selectorLabels" . | nindent 4 }}
---
# FILE: templates/configmap.yaml
apiVersion: v1
kind: ConfigMap
metadata:
  name: {{ include "multi-container-app.fullname" . }}-fluentbit-config
  labels:
    {{- include "multi-container-app.labels" . | nindent 4 }}
data:
  fluent-bit.conf: |
    [SERVICE]
        Daemon Off
        Flush 1
        Log_Level info
        Parsers_File parsers.conf
        HTTP_Server Off
        HTTP_Listen 0.0.0.0
        HTTP_Port 2020

    {{ .Values.fluentbit.config.input | nindent 4 }}

    {{ .Values.fluentbit.config.output | nindent 4 }}

